from pathlib import Path
import json
D=Path('outputs')
def edit(n,pairs):
 p=D/n;s=p.read_text()
 for a,b in pairs:
  if a not in s: print('NOT FOUND',n,a[:70])
  s=s.replace(a,b)
 p.write_text(s)
header='''> 2026-10-12 사용자 검토 반영: 최종 디자인 기준은 시연용. 초안은 UX 참고, 95% 영역은 차이 비교만 수행한다. 분석 건너뛰기와 결과 수정은 선택, 배너는 세션/Seoul 날짜 기준으로 전체 숨김, 예약은 시술→참고 이미지→Hair Note→날짜/시간→검토→모의 완료다. 목표는 Vercel 테스트용 모바일 프로토타입이며 PHASE 02는 아직 시작하지 않는다. 상세 결정/미결정은 OPEN_QUESTIONS를 따른다.\n\n'''
for p in D.glob('*.md'):
 s=p.read_text(); pos=s.index('\n')+1;s=s[:pos]+'\n'+header+s[pos:].lstrip();p.write_text(s)
